export function salvarCadastro(e){const a={nome:e.nome.value,cpf:e.cpf.value,nascimento:e.nascimento.value,email:e.email.value,telefone:e.telefone.value,cep:e.cep.value,endereco:e.endereco.value,cidade:e.cidade.value,estado:e.estado.value};return localStorage.setItem("cadastroONG",JSON.stringify(a)),a}export function carregarCadastro(){const e=localStorage.getItem("cadastroONG");return e?JSON.parse(e):null}